mapper.select:
select count(*)
from objection_opinions oo
where oo.objection_id = #{objectionId}
  and (
    oo.processed_by = #{handlerUserId}
    or exists (
        select 1
        from evaluation_organization_mappings eom
        where eom.user_id = #{handlerUserId}
          and eom.business_type = 'OBJECTION'
          and eom.data_scope in ('BUSINESS','ALL')
    )
  )
